contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 d) public payable {
        require(true);
        bool firstReverted;
        try c.seedMarket{value: 0}(d) { firstReverted = false; } catch { firstReverted = true; }
        bool initAfter = c.initialized();
        uint256 mdAfter = c.marketDrugs();
        bool secondReverted;
        try c.seedMarket{value: 0}(d) { secondReverted = false; } catch { secondReverted = true; }
        assert(!firstReverted && initAfter && mdAfter == d && secondReverted);
    }
    receive() external payable {}
}

