contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 seedDrugs, uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        c.seedMarket(seedDrugs);
        address ceo = c.ceoAddress();
        uint256 ceoBefore = ceo.balance;
        uint256 balanceBefore = address(c).balance;
        uint256 expectedGross = c.calculateDrugBuy(amount, balanceBefore - amount);
        uint256 expectedFee = (expectedGross * 4) / 100;
        uint256 expectedNet = expectedGross - expectedFee;
        c.buyDrugs{value: amount}();
        assert(c.getMyDrugs() == expectedNet && ceo.balance == ceoBefore + (amount * 4) / 100);
    }
    receive() external payable {}
}

